package career.assistant.document.controller;
import career.assistant.document.model.ResumeDownload; import career.assistant.document.service.CoverLetterService; import org.springframework.core.io.ByteArrayResource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.nio.charset.StandardCharsets; import java.util.*;
@RestController @RequestMapping("/api/cover-letters") public class CoverLetterController {private final CoverLetterService service;public CoverLetterController(CoverLetterService s){service=s;}@GetMapping public List<CoverLetterService.LetterResponse> list(){return service.list();}@GetMapping("/{id}") public CoverLetterService.LetterResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping("/{id}/download") public ResponseEntity<ByteArrayResource> download(@PathVariable UUID id,@RequestParam(defaultValue="false") boolean inline){ResumeDownload d=service.download(id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.contentType())).contentLength(d.content().length).header(HttpHeaders.CONTENT_DISPOSITION,(inline?ContentDisposition.inline():ContentDisposition.attachment()).filename(d.filename(),StandardCharsets.UTF_8).build().toString()).header("X-Content-Type-Options","nosniff").body(new ByteArrayResource(d.content()));}}
